"""VRChat auto-rejoin.

Коли інтернет зникає, VRChat викидає з інстансу і показує вікно
"зʼєднання втрачено". Він сам повертається в той самий інстанс лише
після натискання кнопки. Ця програма робить те саме без кнопки:

1. читає лог VRChat і запамʼятовує поточний інстанс;
2. помічає обрив: рядок "Resetting game flow ... [RejoinInstance" (те саме
   вікно) або коли VRChat довго сидить поза світом і нікуди не входить;
3. чекає, поки інтернет повернеться і VRChat перестане пробувати сам;
4. перезапускає VRChat з посиланням на той самий інстанс — до 10 разів;
5. якщо не вийшло (або VRChat закинув у приватний дім) — запускає дім
   у режимі «Друзі+», щоб до тебе могли зайти.

Кожен обрив записується в events.jsonl (його показує vrchat_kicks.py),
а в net.log — коли зникав інтернет і чи був у цей час доступний роутер.
"""
import ctypes
import json
import os
import random
import re
import shutil
import signal
import socket
import sqlite3
import subprocess
import sys
import threading
import time
from pathlib import Path

VERSION = "1.0.0"
VRC_SUBDIR = "steamapps/compatdata/438100/pfx/drive_c/users/steamuser/AppData/LocalLow/VRChat/VRChat"
STEAM_ROOTS = ("~/.local/share/Steam", "~/.steam/steam",
               "~/.var/app/com.valvesoftware.Steam/.local/share/Steam")
UK = os.environ.get("LANG", "").startswith("uk")


def L(uk, en):
    return uk if UK else en


def find_log_dir():
    """Папка логів VRChat (Proton) у будь-якій бібліотеці Steam."""
    if os.environ.get("VRC_LOG_DIR"):
        return Path(os.environ["VRC_LOG_DIR"])
    libs = []
    for root in STEAM_ROOTS:
        root = Path(root).expanduser()
        libs.append(root)
        try:
            vdf = (root / "steamapps/libraryfolders.vdf").read_text(errors="replace")
            libs += [Path(p) for p in re.findall(r'"path"\s+"([^"]+)"', vdf)]
        except OSError:
            pass
    for lib in libs:
        if (lib / VRC_SUBDIR).is_dir():
            return lib / VRC_SUBDIR
    return Path(STEAM_ROOTS[0]).expanduser() / VRC_SUBDIR


LOG_DIR = find_log_dir()
STATE_DIR = Path(os.environ.get("VRC_REJOIN_STATE") or Path.home() / ".local/state/vrchat-auto-rejoin")
VRCX_DB = Path.home() / ".config/VRCX/VRCX.sqlite3"
DRY_RUN = "--dry-run" in sys.argv

GRACE_AFTER_ONLINE = 15      # секунд інтернету, перш ніж щось робити
QUIET_BEFORE_RESTART = 20    # VRChat сам пробує увійти — не заважати
STUCK_AFTER = 90             # поза світом і без спроб входу = застрягла в меню
MAX_WAIT_OFFLINE = 6 * 3600  # довше не чекаємо інтернет
JOIN_TIMEOUT = 150           # скільки чекати входу після перезапуску
LOAD_TIMEOUT = 600           # ...якщо світ уже вантажиться
MAX_TRIES = 10               # спроб повернутись у той самий інстанс
HOME_TRIES = 3               # потім стільки спроб піти додому (Друзі+)

RE_JOINING = re.compile(r"\[Behaviour\] Joining (wrld_[0-9a-f-]+:\S+)")
RE_ROOM = re.compile(r"\[Behaviour\] Entering Room: (.*)")
RE_RESET = re.compile(r'Resetting game flow because "?(.*?)"?: \[([^\]]*)\]')
RE_JOINED = re.compile(r"\[Behaviour\] Finished entering world")
RE_LEFT = re.compile(r"\[Behaviour\] OnLeftRoom")
RE_PROGRESS = re.compile(r"\[Behaviour\] (Joining|Entering Room|Destination (set|requested|fetching)"
                         r"|Switching to network region)")
RE_ME = re.compile(r"post login checks for .* \((usr_[0-9a-f-]+)\)")


def log(msg):
    line = time.strftime("%Y-%m-%d %H:%M:%S ") + msg
    print(line, flush=True)
    with open(STATE_DIR / "rejoin.log", "a") as f:
        f.write(line + "\n")


def save_event(ev):
    with open(STATE_DIR / "events.jsonl", "a") as f:
        f.write(json.dumps(ev, ensure_ascii=False) + "\n")


def notify(msg):
    subprocess.run(["notify-send", "-a", "VRChat", L("VRChat авто-повернення", "VRChat auto-rejoin"), msg],
                   stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)


def online():
    for host in ("api.vrchat.cloud", "1.1.1.1"):
        try:
            socket.create_connection((host, 443), timeout=4).close()
        except OSError:
            return False
    return True


# ---------- дім «Друзі+» ----------

def home_world():
    """Домашній світ з кешу VRCX (там збережений профіль після входу)."""
    try:
        con = sqlite3.connect(f"file:{VRCX_DB}?mode=ro", uri=True, timeout=5)
        row = con.execute("select value from configs where key='config:savedcredentials'").fetchone()
        con.close()
        for uid, v in json.loads(row[0]).items():
            home = v.get("user", {}).get("homeLocation")
            if home and home.startswith("wrld_"):
                return uid, home
    except Exception:
        pass
    return None, None


def friends_plus_home(me, region):
    uid, home = home_world()
    me = me or uid
    if not (me and home):
        return None
    return f"{home}:{random.randint(10000, 99999)}~hidden({me})~region({region})"


def region_of(instance):
    m = re.search(r"~region\((\w+)\)", instance or "")
    return m.group(1) if m else "eu"


# ---------- лог VRChat ----------

class LogFollower:
    """Читає новий текст із найсвіжішого output_log_*.txt."""

    def __init__(self, from_start=False):
        self.path = None
        self.pos = 0
        self.buf = ""
        self.new_file = False
        self._switch(from_start)

    def _newest(self):
        logs = sorted(LOG_DIR.glob("output_log_*.txt"), key=lambda p: p.stat().st_mtime)
        return logs[-1] if logs else None

    def _switch(self, from_start):
        newest = self._newest()
        if newest != self.path:
            self.path = newest
            self.buf = ""
            self.pos = 0 if (from_start or newest is None) else newest.stat().st_size
            return True
        return False

    def lines(self):
        # новий лог (VRChat перезапустився) — читаємо з початку
        if self._switch(from_start=self.path is not None):
            self.new_file = True
        if self.path is None:
            return []
        try:
            with open(self.path, "r", encoding="utf-8", errors="replace") as f:
                f.seek(self.pos)
                chunk = f.read()
                self.pos = f.tell()
        except OSError:
            return []
        self.buf += chunk
        *done, self.buf = self.buf.split("\n")
        return [l.rstrip("\r") for l in done]


# ---------- керування VRChat ----------

def find_pids(match):
    pids = []
    for d in Path("/proc").iterdir():
        if not d.name.isdigit() or int(d.name) == os.getpid():
            continue
        try:
            if match(d):
                pids.append(int(d.name))
        except OSError:
            pass
    return pids


def vrchat_pids():
    return find_pids(lambda d: (d / "comm").read_text().strip() == "VRChat.exe")


def steam_game_pids():
    # процес Steam "reaper SteamLaunch AppId=438100" живе, поки гра не закрилась
    return find_pids(lambda d: b"AppId=438100" in (d / "cmdline").read_bytes()
                     and (d / "comm").read_text().strip() == "reaper")


def wait_gone(get, seconds):
    end = time.time() + seconds
    while time.time() < end:
        if not get():
            return True
        time.sleep(1)
    return not get()


def restart_into(instance):
    url = f"vrchat://launch?ref=vrchat.com&id={instance}"
    if DRY_RUN:
        log(L(f"[тест] перезапустила б VRChat у {instance}", f"[test] would restart VRChat into {instance}"))
        return True
    log(L("закриваю VRChat", "closing VRChat"))
    for pid in vrchat_pids():
        os.kill(pid, signal.SIGTERM)
    if not wait_gone(vrchat_pids, 20):
        for pid in vrchat_pids():
            os.kill(pid, signal.SIGKILL)
    if not wait_gone(steam_game_pids, 60):
        log(L("Steam досі вважає VRChat запущеним — не перезапускаю", "Steam still thinks VRChat is running — not restarting"))
        return False
    time.sleep(5)
    log(L(f"запускаю VRChat у {instance}", f"starting VRChat in {instance}"))
    steam = (["steam"] if shutil.which("steam")
             else ["flatpak", "run", "com.valvesoftware.Steam"])
    subprocess.Popen(steam + ["-applaunch", "438100", url],
                     stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                     start_new_session=True)
    return True


# ---------- журнал інтернету ----------

def gateway():
    try:
        out = subprocess.run(["ip", "-4", "route", "show", "default"],
                             capture_output=True, text=True).stdout.split()
        return out[out.index("via") + 1]
    except (ValueError, IndexError):
        return None


def ping(host):
    return host is not None and subprocess.run(
        ["ping", "-n", "-q", "-c1", "-W1", host],
        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode == 0


def net_watch():
    """Записує тільки зміни: коли зник/повернувся інтернет і роутер."""
    last = None
    since = time.time()
    while True:
        gw = gateway()
        state = (ping(gw), ping("1.1.1.1") or ping("8.8.8.8"))
        if state != last:
            now = time.time()
            if last is not None:
                # перше слово — мітка для vrchat_kicks.py, далі пояснення
                words = {(True, True): ("OK", L("все працює", "all fine")),
                         (True, False): ("NO-INTERNET", L("роутер є, ІНТЕРНЕТУ НЕМАЄ (оператор/модем)",
                                                          "router up, NO INTERNET (ISP/modem)")),
                         (False, False): ("NO-ROUTER", L("РОУТЕР НЕДОСТУПНИЙ (перезавантаження/кабель)",
                                                         "ROUTER UNREACHABLE (reboot/cable)")),
                         (False, True): ("NO-PING", L("роутер не відповідає на ping, інтернет є",
                                                      "router ignores ping, internet works"))}
                tag, text = words[state]
                with open(STATE_DIR / "net.log", "a") as f:
                    f.write(time.strftime("%Y-%m-%d %H:%M:%S ") + f"{tag} {text}  ("
                            + L("попередній стан тривав", "previous state lasted")
                            + f" {now - since:.0f} s)\n")
            last, since = state, now
        time.sleep(2)


# ---------- старий журнал → events.jsonl ----------

def import_old_log():
    """Один раз переносить обриви зі старого rejoin.log у events.jsonl."""
    src, dst = STATE_DIR / "rejoin.log", STATE_DIR / "events.jsonl"
    if dst.exists() or not src.exists():
        return
    ev = None
    out = []
    for line in src.read_text(errors="replace").splitlines():
        try:
            ts = time.mktime(time.strptime(line[:19], "%Y-%m-%d %H:%M:%S"))
        except ValueError:
            continue
        msg = line[20:]
        if msg.startswith("обрив: "):
            reason, _, inst = msg[7:].rpartition("; інстанс ")
            ev = {"start": ts, "reason": reason.strip('"'), "instance": inst, "tries": 0}
        elif ev is None:
            continue
        elif msg.startswith("закриваю VRChat"):
            ev["tries"] += 1
        elif msg.startswith(("повернулась в інстанс", "VRChat повернувся сам", "увійшла в інший")):
            ev["end"] = ts
            ev["result"] = ("same" if msg.startswith("повернулась") else
                            "self" if msg.startswith("VRChat") else "other")
            if ev["result"] == "other":
                ev["landed"] = msg.split(": ", 1)[1]
            out.append(ev)
            ev = None
        elif "здаюсь" in msg:
            ev["end"], ev["result"] = ts, "failed"
            out.append(ev)
            ev = None
    with open(dst, "w") as f:
        for e in out:
            f.write(json.dumps(e, ensure_ascii=False) + "\n")


# ---------- основний цикл ----------

class Rejoiner:
    def __init__(self):
        self.instance = None       # останній інстанс, де повністю увійшла
        self.joining = None        # куди зараз входить
        self.room = None           # назва світу
        self.me = None
        self.in_room = False
        self.left_at = None
        self.last_progress = 0.0
        self.last_reason = None
        self.ev = None             # поточний обрив
        self.online_since = None
        self.restarted_at = None
        self.loading = False
        self.replaying = False     # читаємо старий лог при старті — не діяти

    # --- події з логу ---

    def feed(self, line, now):
        if m := RE_ME.search(line):
            self.me = m.group(1)
        if RE_PROGRESS.search(line):
            self.last_progress = now
        if m := RE_ROOM.search(line):
            self.room = m.group(1).strip()
        if m := RE_JOINING.search(line):
            self.joining = m.group(1)
            self.loading = True
        if RE_LEFT.search(line):
            self.in_room = False
            self.loading = False
            self.left_at = now
        if m := RE_RESET.search(line):
            reason, flags = m.group(1), m.group(2)
            if reason != "Destination instance set":
                self.in_room = False
                self.loading = False
                self.left_at = self.left_at or now
                self.last_reason = reason
                if self.replaying:
                    pass
                elif self.ev and self.restarted_at:
                    self.attempt_failed(reason)
                elif "RejoinInstance" in flags and self.instance and not self.ev:
                    self.start(reason, now)
        if RE_JOINED.search(line):
            self.in_room = True
            self.left_at = None
            self.loading = False
            if self.joining:
                self.instance = self.joining
            if self.ev:
                self.joined(now)
            self.last_reason = None

    def new_vrchat(self):
        """VRChat запустився заново (наш перезапуск або її власний)."""
        self.in_room = False
        self.loading = False
        self.left_at = None
        if not self.ev:
            self.instance = None

    # --- обрив ---

    def start(self, reason, now):
        self.ev = {"start": now, "reason": reason, "instance": self.instance,
                   "world": self.room, "tries": 0, "home_tries": 0}
        self.online_since = None
        self.restarted_at = None
        log(L(f"обрив: {reason}; інстанс {self.instance}", f"kicked: {reason}; instance {self.instance}"))

    def finish(self, result, now, **extra):
        self.ev.update(end=now, result=result, **extra)
        save_event(self.ev)
        self.ev = None
        self.restarted_at = None

    def joined(self, now):
        ev = self.ev
        if self.instance == ev["instance"]:
            if ev["tries"]:
                log(L("повернулась в інстанс ✔", "back in the instance ✔"))
                notify(L("Повернула тебе в інстанс після обриву", "You are back in your instance"))
                self.finish("same", now)
            else:
                log(L("VRChat повернувся сам ✔", "VRChat rejoined by itself ✔"))
                self.finish("self", now)
            return
        home = self.instance == ev.get("home_target")
        uid, home_id = home_world()
        dumped_private = (not home and "~private(" in self.instance
                          and home_id and self.instance.startswith(home_id))
        if dumped_private and ev["home_tries"] < HOME_TRIES:
            # VRChat сам закинув у приватний дім — туди ніхто не зайде
            log(L(f"VRChat закинув у приватний дім ({self.instance}) — переходжу в «Друзі+»",
                  f"VRChat put you in a private home ({self.instance}) — switching to Friends+"))
            ev["skip_to_home"] = True
            self.restarted_at = None
            self.online_since = None
            self.last_progress = 0
            return
        if home:
            log(L(f"дім «Друзі+»: {self.instance} ✔", f"Friends+ home: {self.instance} ✔"))
            notify(L("Не вдалося повернутись — відкрила дім «Друзі+»", "Could not rejoin — opened your home as Friends+"))
            self.finish("home", now, landed=self.instance)
        else:
            log(L(f"увійшла в інший інстанс: {self.instance}", f"ended up in another instance: {self.instance}"))
            self.finish("other", now, landed=self.instance)

    def attempt_failed(self, why):
        log(L(f"спроба не вдалася: {why}", f"attempt failed: {why}"))
        self.ev.setdefault("errors", []).append(why)
        self.restarted_at = None
        self.online_since = None

    # --- кожні 2 секунди ---

    def tick(self, now):
        if not self.ev:
            wait = LOAD_TIMEOUT if self.loading else STUCK_AFTER
            stuck = (self.instance and not self.in_room and self.left_at
                     and now - self.left_at > wait
                     and now - self.last_progress > wait
                     and vrchat_pids())
            if stuck:
                self.start(self.last_reason or L("застрягла поза світом", "stuck outside a world"), now)
            return
        ev = self.ev
        if self.restarted_at:
            limit = LOAD_TIMEOUT if self.loading else JOIN_TIMEOUT
            if now - self.restarted_at > limit:
                self.attempt_failed(L("після перезапуску вхід не відбувся", "no join after the restart"))
            return
        if now - ev["start"] > MAX_WAIT_OFFLINE:
            log(L("інтернет не повертався надто довго — здаюсь", "internet was gone too long — giving up"))
            notify(L("Інтернету не було понад 6 годин — повернути не вдалося", "No internet for over 6 hours — could not rejoin"))
            self.finish("failed", now)
            return
        if not online():
            self.online_since = None
            return
        self.online_since = self.online_since or now
        if now - self.online_since < GRACE_AFTER_ONLINE:
            return
        if now - self.last_progress < QUIET_BEFORE_RESTART:
            return  # VRChat зараз сам пробує увійти
        if ev["tries"] < MAX_TRIES and not ev.get("skip_to_home"):
            ev["tries"] += 1
            target = ev["instance"]
            log(L(f"спроба {ev['tries']}/{MAX_TRIES}: повертаю в інстанс", f"try {ev['tries']}/{MAX_TRIES}: rejoining the instance"))
        elif ev["home_tries"] < HOME_TRIES:
            target = friends_plus_home(self.me, region_of(ev["instance"]))
            if not target:
                log(L("не знаю домашній світ (потрібен VRCX) — здаюсь", "home world unknown (needs VRCX) — giving up"))
                self.finish("failed", now)
                return
            ev["home_tries"] += 1
            ev["home_target"] = target
            log(L(f"дім «Друзі+», спроба {ev['home_tries']}/{HOME_TRIES}", f"Friends+ home, try {ev['home_tries']}/{HOME_TRIES}"))
        else:
            log(L("спроби вичерпано — здаюсь", "out of tries — giving up"))
            notify(L("Не вдалося повернути тебе в VRChat", "Could not get you back into VRChat"))
            self.finish("failed", now)
            return
        if restart_into(target):
            self.restarted_at = time.time()
            self.last_progress = self.restarted_at
            if DRY_RUN:
                self.finish("dry-run", now)
        else:
            self.online_since = None


def set_process_name(name):
    """Імʼя процесу для VR Auto Launcher (інакше видно лише "python3")."""
    try:
        ctypes.CDLL(None).prctl(15, name.encode(), 0, 0, 0)  # PR_SET_NAME
    except (OSError, AttributeError):
        pass


def main():
    set_process_name("vrchat-rejoin")
    STATE_DIR.mkdir(parents=True, exist_ok=True)
    import_old_log()
    threading.Thread(target=net_watch, daemon=True).start()

    follower = LogFollower(from_start=True)
    r = Rejoiner()
    # швидко прочитати вже наявний лог, щоб знати поточний інстанс
    r.replaying = True
    for line in follower.lines():
        r.feed(line, 0)
    r.replaying = False
    r.left_at = time.time() if r.left_at else None
    follower.new_file = False
    log(L("старт", "start") + f" {VERSION}; " + L("поточний інстанс", "current instance")
        + f": {r.instance}; " + L("логи VRChat", "VRChat logs") + f": {LOG_DIR}" + (" [test]" if DRY_RUN else ""))

    while True:
        lines = follower.lines()
        if follower.new_file:
            follower.new_file = False
            r.new_vrchat()
        now = time.time()
        for line in lines:
            r.feed(line, now)
        r.tick(now)
        time.sleep(2)


if __name__ == "__main__":
    main()
